2041:   const sc = view.scale;
2042:   for (const pad of G.pads) {
2043:     const x = SX(pad.x);
2044:     const y = SY(pad.y);
2045:     const base = (pad.big ? 17 : 12) * sc;
2046:     if (!pad.active) {
2047:       const fade = clamp(1 - pad.timer / pad.respawn, 0, 1);
2048:       ctx.save();
2049:       ctx.globalAlpha = 0.12 + fade * 0.14;
2050:       ctx.strokeStyle = pad.big ? COLORS.gold : COLORS.cyan;
2051:       ctx.lineWidth = Math.max(0.8, 1.2 * sc);
2052:       ctx.beginPath();
2053:       ctx.arc(x, y, base * 0.72, 0, TAU);
2054:       ctx.stroke();
2055:       ctx.restore();
2056:       continue;
2057:     }
2058:     const pulse = 1 + Math.sin(G.time * 3.2 + pad.phase) * 0.08;
2059:     const color = pad.big ? COLORS.gold : COLORS.cyan;
2060:     const glow = ctx.createRadialGradient(x, y, 0, x, y, base * 2.6);
2061:     glow.addColorStop(0, pad.big ? "rgba(255,209,102,0.32)" : "rgba(54,240,255,0.24)");
2062:     glow.addColorStop(1, pad.big ? "rgba(255,209,102,0)" : "rgba(54,240,255,0)");
2063:     ctx.fillStyle = glow;
2064:     ctx.beginPath();
2065:     ctx.arc(x, y, base * 2.6, 0, TAU);
2066:     ctx.fill();
2067: 
2068:     ctx.save();
2069:     ctx.translate(x, y);
2070:     ctx.scale(pulse, pulse * 0.8);
2071:     ctx.rotate(Math.PI / 6);
2072:     ctx.beginPath();
2073:     for (let i = 0; i < 6; i++) {
2074:       const a = (i / 6) * TAU;
2075:       const px = Math.cos(a) * base;
2076:       const py = Math.sin(a) * base;
2077:       if (i === 0) ctx.moveTo(px, py);
2078:       else ctx.lineTo(px, py);
2079:     }
2080:     ctx.closePath();
2081:     ctx.fillStyle = pad.big ? "rgba(255,209,102,0.18)" : "rgba(54,240,255,0.14)";
2082:     ctx.fill();
2083:     ctx.strokeStyle = color;
2084:     ctx.globalAlpha = 0.16;
2085:     ctx.lineWidth = Math.max(4, 7 * sc);
2086:     ctx.stroke();
2087:     ctx.globalAlpha = 1;
2088:     ctx.lineWidth = Math.max(1, 1.6 * sc);
2089:     ctx.stroke();
2090:     ctx.restore();
2091: 
2092:     ctx.fillStyle = color;
2093:     ctx.globalAlpha = 0.8;
2094:     ctx.beginPath();
2095:     ctx.arc(x, y, Math.max(1, base * 0.16), 0, TAU);
2096:     ctx.fill();
2097:     ctx.globalAlpha = 1;
2098:   }
2099: }
