2118: function drawShadows() {
2119:   const sc = view.scale;
2120:   const p = G.player;
2121:   const b = G.bot;
2122:   const ball = G.ball;
2123: 
2124:   for (const car of [p, b]) {
2125:     const s = carScale(car.y);
2126:     ctx.save();
2127:     ctx.translate(SX(car.x) + car.z * 0.12, SY(car.y, 0) + car.z * 0.1);
2128:     ctx.rotate(car.angle);
2129:     ctx.globalAlpha = 0.34 / (1 + car.z / 240);
2130:     ctx.fillStyle = "#000";
2131:     roundRectPath(-CAR.l * s * 0.52, -CAR.w * s * 0.54, CAR.l * s * 1.04, CAR.w * s * 1.08, CAR.w * s * 0.3);
2132:     ctx.fill();
2133:     ctx.restore();
2134:   }
2135: 
2136:   const r = BALL_R * sc;
2137:   const alpha = 0.38 / (1 + ball.z / 260);
2138:   ctx.save();
2139:   ctx.translate(SX(ball.x) + ball.z * 0.1, SY(ball.y, 0) + ball.z * 0.08);
2140:   ctx.scale(1, 0.46);
2141:   const sg = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 1.4);
2142:   sg.addColorStop(0, `rgba(0,0,0,${alpha})`);
2143:   sg.addColorStop(1, "rgba(0,0,0,0)");
2144:   ctx.fillStyle = sg;
2145:   ctx.beginPath();
2146:   ctx.arc(0, 0, r * 1.4, 0, TAU);
2147:   ctx.fill();
2148:   ctx.restore();
