2155: function drawCar(car) {
2156:   const s = carScale(car.y);
2157:   const px = SX(car.x);
2158:   const py = SY(car.y, car.z);
2159:   const L = CAR.l * s;
2160:   const W = CAR.w * s;
2161:   const team = car.isPlayer ? COLORS.cyan : COLORS.pink;
2162: 
2163:   ctx.save();
2164:   ctx.translate(px, py);
2165:   ctx.rotate(car.angle);
2166: 
2167:   // Ground underglow
2168:   if (car.z < 22) {
2169:     ctx.save();
2170:     ctx.globalCompositeOperation = "lighter";
2171:     const ug = ctx.createRadialGradient(0, 0, 0, 0, 0, L * 0.72);
2172:     ug.addColorStop(0, car.isPlayer ? "rgba(54,240,255,0.17)" : "rgba(255,61,127,0.16)");
2173:     ug.addColorStop(1, "rgba(0,0,0,0)");
2174:     ctx.fillStyle = ug;
2175:     ctx.beginPath();
2176:     ctx.ellipse(0, 0, L * 0.72, W * 0.8, 0, 0, TAU);
2177:     ctx.fill();
2178:     ctx.restore();
2179:   }
2180: 
2181:   // Boost flame
2182:   if (car.boosting) {
2183:     const flick = 0.72 + Math.sin(G.time * 38 + car.x) * 0.2 + Math.random() * 0.16;
2184:     const len = L * (0.34 + flick * 0.24);
2185:     ctx.save();
2186:     ctx.globalCompositeOperation = "lighter";
2187:     const fg = ctx.createLinearGradient(-L * 0.46, 0, -L * 0.46 - len, 0);
2188:     fg.addColorStop(0, "rgba(255,248,200,0.95)");
2189:     fg.addColorStop(0.45, "rgba(255,190,70,0.8)");
2190:     fg.addColorStop(1, "rgba(255,70,30,0)");
2191:     ctx.fillStyle = fg;
2192:     for (const oy of [-W * 0.22, W * 0.22]) {
2193:       ctx.beginPath();
2194:       ctx.moveTo(-L * 0.44, oy - W * 0.09);
2195:       ctx.quadraticCurveTo(-L * 0.44 - len * 0.55, oy, -L * 0.44 - len, oy);
2196:       ctx.quadraticCurveTo(-L * 0.44 - len * 0.55, oy, -L * 0.44, oy + W * 0.09);
2197:       ctx.closePath();
2198:       ctx.fill();
2199:     }
2200:     ctx.restore();
2201:   }
2202: 
2203:   // Wheels
2204:   ctx.fillStyle = "#04080b";
2205:   ctx.strokeStyle = "rgba(190,230,240,0.16)";
2206:   ctx.lineWidth = Math.max(0.5, 0.8 * s);
2207:   const wheelW = L * 0.2;
2208:   const wheelH = W * 0.16;
2209:   for (const wx of [-L * 0.29, L * 0.29]) {
2210:     for (const wy of [-W * 0.49, W * 0.49]) {
2211:       roundRectPath(wx - wheelW / 2, wy - wheelH / 2, wheelW, wheelH, wheelH * 0.4);
2212:       ctx.fill();
2213:       ctx.stroke();
2214:     }
2215:   }
2216: 
2217:   // Chassis
2218:   const bg = ctx.createLinearGradient(0, -W / 2, 0, W / 2);
2219:   bg.addColorStop(0, "#344854");
2220:   bg.addColorStop(0.42, "#1a2b37");
2221:   bg.addColorStop(0.78, "#0d1922");
2222:   bg.addColorStop(1, "#071017");
2223:   ctx.fillStyle = bg;
2224:   ctx.strokeStyle = team;
2225:   roundRectPath(-L / 2, -W / 2, L, W, W * 0.34);
2226:   ctx.fill();
2227:   ctx.globalAlpha = 0.22;
2228:   ctx.lineWidth = Math.max(4, 6 * s);
2229:   ctx.stroke();
2230:   ctx.globalAlpha = 1;
2231:   ctx.lineWidth = Math.max(0.9, 1.6 * s);
2232:   ctx.stroke();
2233: 
2234:   // Rear spoiler
2235:   ctx.fillStyle = "#0a1219";
2236:   roundRectPath(-L * 0.54, -W * 0.55, L * 0.1, W * 1.1, W * 0.08);
2237:   ctx.fill();
2238:   ctx.strokeStyle = "rgba(255,255,255,0.13)";
2239:   ctx.lineWidth = Math.max(0.5, 0.7 * s);
2240:   ctx.stroke();
2241: 
2242:   // Hood / front
2243:   const hood = ctx.createLinearGradient(L * 0.1, 0, L * 0.52, 0);
2244:   hood.addColorStop(0, car.isPlayer ? "rgba(54,240,255,0.22)" : "rgba(255,61,127,0.22)");
2245:   hood.addColorStop(1, "rgba(255,255,255,0.03)");
2246:   ctx.fillStyle = hood;
2247:   roundRectPath(L * 0.05, -W * 0.43, L * 0.41, W * 0.86, W * 0.2);
2248:   ctx.fill();
2249: 
2250:   // Center stripe
2251:   ctx.fillStyle = car.isPlayer ? "rgba(157,251,255,0.32)" : "rgba(255,155,189,0.3)";
2252:   roundRectPath(-L * 0.31, -W * 0.07, L * 0.72, W * 0.14, W * 0.05);
2253:   ctx.fill();
2254: 
2255:   // Windshield
2256:   const wg = ctx.createLinearGradient(0, -W * 0.3, 0, W * 0.3);
2257:   wg.addColorStop(0, "#0b2029");
2258:   wg.addColorStop(0.45, "#164451");
2259:   wg.addColorStop(1, "#07151c");
2260:   ctx.fillStyle = wg;
2261:   ctx.beginPath();
2262:   ctx.moveTo(-L * 0.1, -W * 0.33);
2263:   ctx.lineTo(L * 0.17, -W * 0.25);
2264:   ctx.lineTo(L * 0.2, W * 0.25);
2265:   ctx.lineTo(-L * 0.1, W * 0.33);
2266:   ctx.closePath();
2267:   ctx.fill();
2268:   ctx.strokeStyle = "rgba(157,251,255,0.16)";
2269:   ctx.lineWidth = Math.max(0.5, 0.8 * s);
2270:   ctx.stroke();
2271: 
2272:   // Headlights
2273:   ctx.fillStyle = "rgba(225,255,255,0.88)";
2274:   for (const hy of [-W * 0.3, W * 0.3]) {
2275:     ctx.beginPath();
2276:     ctx.ellipse(L * 0.43, hy, L * 0.045, W * 0.055, 0, 0, TAU);
2277:     ctx.fill();
2278:   }
2279: 
2280:   // Flip energy ring
2281:   if (car.flip > 0) {
2282:     ctx.save();
2283:     ctx.globalCompositeOperation = "lighter";
2284:     ctx.globalAlpha = clamp(car.flip * 3, 0, 1) * 0.75;
2285:     ctx.strokeStyle = team;
2286:     ctx.beginPath();
2287:     ctx.ellipse(0, 0, L * 0.7, W * 0.62, 0, 0, TAU);
2288:     ctx.lineWidth = Math.max(5, 8 * s);
2289:     ctx.globalAlpha *= 0.25;
2290:     ctx.stroke();
2291:     ctx.globalAlpha = clamp(car.flip * 3, 0, 1) * 0.75;
2292:     ctx.lineWidth = Math.max(1, 2 * s);
2293:     ctx.stroke();
2294:     ctx.restore();
2295:   }
2296: 
2297:   ctx.restore();
2298: 
2299:   // Nameplate
2300:   if (G.phase !== "menu") {
2301:     drawNameplate(car, px, py - L * 0.62 - 13);
2302:   }
2303: }
