2326: function drawBall() {
2327:   const b = G.ball;
2328:   const sc = view.scale;
2329:   const r = BALL_R * sc;
2330:   const x = SX(b.x);
2331:   const y = SY(b.y, b.z);
2332: 
2333:   ctx.save();
2334:   ctx.translate(x, y);
2335:   // Soft halo behind the ball (cheaper than shadowBlur)
2336:   const halo = ctx.createRadialGradient(0, 0, r * 0.8, 0, 0, r * 1.9);
2337:   halo.addColorStop(0, "rgba(157,251,255,0.24)");
2338:   halo.addColorStop(1, "rgba(157,251,255,0)");
2339:   ctx.fillStyle = halo;
2340:   ctx.beginPath();
2341:   ctx.arc(0, 0, r * 1.9, 0, TAU);
2342:   ctx.fill();
2343: 
2344:   const g = ctx.createRadialGradient(-r * 0.38, -r * 0.44, r * 0.06, 0, 0, r * 1.08);
2345:   g.addColorStop(0, "#ffffff");
2346:   g.addColorStop(0.3, "#e5ffff");
2347:   g.addColorStop(0.66, "#a8dfe3");
2348:   g.addColorStop(1, "#4f7d83");
2349:   ctx.fillStyle = g;
2350:   ctx.beginPath();
2351:   ctx.arc(0, 0, r, 0, TAU);
2352:   ctx.fill();
2353: 
2354:   // Panels
2355:   ctx.save();
2356:   ctx.beginPath();
2357:   ctx.arc(0, 0, r * 0.985, 0, TAU);
2358:   ctx.clip();
2359:   ctx.rotate(b.spin);
2360:   ctx.strokeStyle = "rgba(28,72,80,0.48)";
2361:   ctx.lineWidth = Math.max(0.7, r * 0.07);
2362:   ctx.beginPath();
2363:   for (let i = 0; i <= 5; i++) {
2364:     const a = (i / 5) * TAU - Math.PI / 2;
2365:     const px = Math.cos(a) * r * 0.36;
2366:     const py = Math.sin(a) * r * 0.36;
2367:     if (i === 0) ctx.moveTo(px, py);
2368:     else ctx.lineTo(px, py);
2369:   }
2370:   ctx.closePath();
2371:   ctx.stroke();
2372:   for (let i = 0; i < 5; i++) {
2373:     const a = (i / 5) * TAU - Math.PI / 2;
2374:     ctx.beginPath();
2375:     ctx.moveTo(Math.cos(a) * r * 0.36, Math.sin(a) * r * 0.36);
2376:     ctx.lineTo(Math.cos(a) * r * 1.05, Math.sin(a) * r * 1.05);
2377:     ctx.stroke();
2378:   }
2379:   ctx.restore();
2380: 
2381:   // Rim + highlight
2382:   ctx.strokeStyle = "rgba(255,255,255,0.55)";
2383:   ctx.lineWidth = Math.max(0.5, r * 0.045);
2384:   ctx.beginPath();
2385:   ctx.arc(0, 0, r * 0.96, 0, TAU);
2386:   ctx.stroke();
2387: 
2388:   const hl = ctx.createRadialGradient(-r * 0.35, -r * 0.42, 0, -r * 0.35, -r * 0.42, r * 0.55);
2389:   hl.addColorStop(0, "rgba(255,255,255,0.82)");
2390:   hl.addColorStop(1, "rgba(255,255,255,0)");
2391:   ctx.fillStyle = hl;
2392:   ctx.beginPath();
2393:   ctx.arc(-r * 0.35, -r * 0.42, r * 0.55, 0, TAU);
2394:   ctx.fill();
2395:   ctx.restore();
2396: }
