2398: function drawParticles() {
2399:   const sc = view.scale;
2400:   ctx.save();
2401:   for (const p of G.particles) {
2402:     const lifeT = clamp(p.life / p.max, 0, 1);
2403:     const x = SX(p.x);
2404:     const y = SY(p.y, p.z);
2405:     if (x < -40 || x > view.w + 40 || y < -40 || y > view.h + 40) continue;
2406: 
2407:     if (p.kind === "spark") {
2408:       ctx.globalCompositeOperation = "lighter";
2409:       ctx.globalAlpha = lifeT * 0.9;
2410:       ctx.strokeStyle = p.color;
2411:       ctx.lineWidth = Math.max(0.6, p.size * sc * 0.8);
2412:       ctx.beginPath();
2413:       ctx.moveTo(x, y);
2414:       ctx.lineTo(SX(p.x - p.vx * 0.022), SY(p.y - p.vy * 0.022, p.z - p.vz * 0.022));
2415:       ctx.stroke();
2416:     } else if (p.kind === "confetti") {
2417:       ctx.globalCompositeOperation = "source-over";
2418:       ctx.globalAlpha = lifeT;
2419:       ctx.fillStyle = p.color;
2420:       ctx.save();
2421:       ctx.translate(x, y);
2422:       ctx.rotate(p.rot);
2423:       ctx.fillRect(-p.size * sc * 0.5, -p.size * sc * 0.28, p.size * sc, p.size * sc * 0.56);
2424:       ctx.restore();
2425:     } else {
2426:       ctx.globalCompositeOperation = "lighter";
2427:       ctx.globalAlpha = lifeT * 0.55;
2428:       const rr = p.size * sc * (1.4 - lifeT * 0.4);
2429:       const pg = ctx.createRadialGradient(x, y, 0, x, y, rr);
2430:       pg.addColorStop(0, p.color);
2431:       pg.addColorStop(1, "rgba(0,0,0,0)");
2432:       ctx.fillStyle = pg;
2433:       ctx.beginPath();
2434:       ctx.arc(x, y, rr, 0, TAU);
2435:       ctx.fill();
2436:     }
2437:   }
2438:   ctx.restore();
2439: }
