2441: function drawCrowdLights() {
2442:   const t = G.time;
2443:   ctx.save();
2444:   ctx.globalCompositeOperation = "lighter";
2445:   for (let i = 0; i < view.crowd.length; i += 7) {
2446:     const c = view.crowd[i];
2447:     const x = SX(c.x);
2448:     const y = SY(c.y);
2449:     if (x < -8 || x > view.w + 8 || y < -8 || y > view.h + 8) continue;
2450:     const tw = Math.max(0, Math.sin(t * c.speed * 1.8 + c.phase));
2451:     if (tw < 0.15) continue;
2452:     ctx.globalAlpha = tw * 0.5;
2453:     ctx.fillStyle = c.c;
2454:     ctx.beginPath();
2455:     ctx.arc(x, y, c.r * 1.25, 0, TAU);
2456:     ctx.fill();
2457:   }
2458:   ctx.restore();
2459: }
