2461: /* ---------------- Frame ---------------- */
2462: 
2463: function render() {
2464:   ctx.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
2465:   if (!view.rect.w) return;
2466: 
2467:   ctx.save();
2468:   if (G.shake > 0.2) {
2469:     ctx.clearRect(0, 0, view.w, view.h);
2470:     ctx.translate(rand(-1, 1) * G.shake * 0.55, rand(-1, 1) * G.shake * 0.4);
2471:   }
2472: 
2473:   ctx.drawImage(staticCanvas, 0, 0, view.w, view.h);
2474:   drawCrowdLights();
2475:   drawPads();
2476:   drawTrail();
2477:   drawShadows();
2478: 
2479:   const ents = [
2480:     { y: G.player.y + G.player.z * 0.35, draw: () => drawCar(G.player) },
2481:     { y: G.bot.y + G.bot.z * 0.35, draw: () => drawCar(G.bot) },
2482:     { y: G.ball.y + G.ball.z * 0.22, draw: () => drawBall() }
2483:   ];
2484:   ents.sort((a, b) => a.y - b.y);
2485:   for (const e of ents) e.draw();
2486: 
2487:   drawGoalFrame(-1);
2488:   drawGoalFrame(1);
2489:   drawParticles();
2490:   ctx.restore();
2491: 
2492:   if (G.flash > 0) {
2493:     ctx.save();
2494:     ctx.globalAlpha = Math.min(0.55, G.flash * 0.6);
2495:     ctx.fillStyle = G.flashColor;
2496:     ctx.fillRect(0, 0, view.w, view.h);
2497:     ctx.restore();
2498:   }
2499: }
