100:   w: 0,
101:   h: 0,
102:   dpr: 1,
103:   scale: 1,
104:   cx: 0,
105:   top: 0,
106:   rect: { x: 0, y: 0, w: 0, h: 0 },
107:   landscape: false,
108:   bg: null,
109:   crowd: []
110: };
111: 
112: const SX = (x) => view.cx + x * view.scale;
113: const SY = (y, z = 0) => view.top + (y + FIELD.h / 2) * view.scale - z * view.scale * Z_SCALE;
114: 
115: function resize() {
116:   view.w = window.innerWidth;
117:   view.h = window.innerHeight;
118:   view.dpr = Math.min(window.devicePixelRatio || 1, 2);
119:   canvas.width = Math.round(view.w * view.dpr);
120:   canvas.height = Math.round(view.h * view.dpr);
121:   canvas.style.width = view.w + "px";
122:   canvas.style.height = view.h + "px";
123: 
124:   const landscape = view.w > view.h;
125:   view.landscape = landscape;
126:   const small = view.h < 620;
127:   const safe = 0;
128:   let top = landscape ? 76 : 90;
129:   let bottom = landscape ? 16 : small ? 168 : 195;
130:   let availW = view.w - (landscape ? 310 : 20);
131:   let availH = view.h - top - bottom - safe;
132: 
133:   if (landscape && availW < 240) availW = view.w - 26;
134:   if (availW < 200) availW = view.w - 18;
135:   if (availH < 200) availH = view.h * 0.5;
136: 
137:   view.scale = Math.min(availW / FIELD.w, availH / FIELD.h);
138:   const fw = FIELD.w * view.scale;
139:   const fh = FIELD.h * view.scale;
140:   view.cx = view.w / 2;
141:   view.top = top + Math.max(0, (availH - fh) / 2);
142:   view.rect = { x: view.cx - fw / 2, y: view.top, w: fw, h: fh };
143: 
144:   buildCrowd();
145:   rebuildStatic();
146: }
147: 
148: function rebuildStatic() {
149:   if (!view.rect.w) return;
150:   staticCanvas.width = Math.round(view.w * view.dpr);
151:   staticCanvas.height = Math.round(view.h * view.dpr);
152:   staticCtx.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
153:   staticCtx.clearRect(0, 0, view.w, view.h);
154: 
155:   const prev = ctx;
156:   ctx = staticCtx;
157:   view.bg = ctx.createLinearGradient(0, 0, 0, view.h);
158:   view.bg.addColorStop(0, "#081722");
159:   view.bg.addColorStop(0.45, "#050d15");
160:   view.bg.addColorStop(1, "#03060a");
161: 
162:   drawBackground();
163:   drawStadium();
164:   drawField();
165:   drawGoalNet(-1);
166:   drawGoalNet(1);
167:   ctx = prev;
168: }
169: 
170: function buildCrowd() {
171:   view.crowd = [];
172:   const palette = [COLORS.cyan, COLORS.pink, COLORS.gold, "#d8f6ff", "#8aabc0"];
173:   for (let i = 0; i < 300; i++) {
174:     const side = Math.floor(Math.random() * 4);
175:     let x, y;
176:     if (side === 0) {
177:       x = -FIELD.w / 2 - rand(34, 150);
178:       y = rand(-FIELD.h / 2 - 110, FIELD.h / 2 + 110);
179:     } else if (side === 1) {
180:       x = FIELD.w / 2 + rand(34, 150);
181:       y = rand(-FIELD.h / 2 - 110, FIELD.h / 2 + 110);
182:     } else if (side === 2) {
183:       x = rand(-FIELD.w / 2 - 130, FIELD.w / 2 + 130);
184:       y = -FIELD.h / 2 - rand(40, 122);
185:     } else {
186:       x = rand(-FIELD.w / 2 - 130, FIELD.w / 2 + 130);
187:       y = FIELD.h / 2 + rand(40, 122);
188:     }
189:     view.crowd.push({
190:       x,
191:       y,
192:       c: palette[Math.floor(Math.random() * palette.length)],
193:       r: rand(1, 2.4),
194:       phase: rand(0, TAU),
195:       speed: rand(0.6, 2.2),
196:       a: rand(0.16, 0.52)
197:     });
198:   }
199: }
