203: const Sound = {
204:   ctx: null,
205:   master: null,
206:   boostGain: null,
207:   enabled: true,
208:   lastHit: 0,
209: 
210:   init() {
211:     if (this.ctx) {
212:       if (this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
213:       return;
214:     }
215:     const AC = window.AudioContext || window.webkitAudioContext;
216:     if (!AC) return;
217:     try {
218:       this.ctx = new AC();
219:     } catch {
220:       this.ctx = null;
221:     }
222:     if (!this.ctx) return;
223:     this.master = this.ctx.createGain();
224:     this.master.gain.value = 0.55;
225:     this.master.connect(this.ctx.destination);
226: 
227:     const len = Math.floor(this.ctx.sampleRate * 2);
228:     const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
229:     const data = buf.getChannelData(0);
230:     for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
231:     const src = this.ctx.createBufferSource();
232:     src.buffer = buf;
233:     src.loop = true;
234:     const bp = this.ctx.createBiquadFilter();
235:     bp.type = "bandpass";
236:     bp.frequency.value = 900;
237:     bp.Q.value = 0.7;
238:     const gain = this.ctx.createGain();
239:     gain.gain.value = 0;
240:     src.connect(bp);
241:     bp.connect(gain);
242:     gain.connect(this.master);
243:     src.start();
244:     this.boostGain = gain;
245:   },
246: 
247:   setBoost(on) {
248:     G.boostSound = !!on;
249:     if (!this.ctx || !this.boostGain) return;
250:     const v = on && this.enabled ? 0.05 : 0;
251:     this.boostGain.gain.setTargetAtTime(v, this.ctx.currentTime, 0.06);
252:   },
253: 
254:   tone(freq, dur = 0.12, type = "sine", vol = 0.1, when = 0) {
255:     if (!this.enabled || !this.ctx) return;
256:     const t = this.ctx.currentTime + when;
257:     const o = this.ctx.createOscillator();
258:     const g = this.ctx.createGain();
259:     o.type = type;
260:     o.frequency.setValueAtTime(freq, t);
261:     g.gain.setValueAtTime(0.0001, t);
262:     g.gain.linearRampToValueAtTime(vol, t + 0.01);
263:     g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
264:     o.connect(g);
265:     g.connect(this.master);
266:     o.start(t);
267:     o.stop(t + dur + 0.04);
268:   },
269: 
270:   noise(dur = 0.1, vol = 0.1, freq = 900, q = 1) {
271:     if (!this.enabled || !this.ctx) return;
272:     const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
273:     const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
274:     const data = buf.getChannelData(0);
275:     for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
276:     const src = this.ctx.createBufferSource();
277:     src.buffer = buf;
278:     const f = this.ctx.createBiquadFilter();
279:     f.type = "bandpass";
280:     f.frequency.value = freq;
281:     f.Q.value = q;
282:     const g = this.ctx.createGain();
283:     g.gain.value = vol;
284:     src.connect(f);
285:     f.connect(g);
286:     g.connect(this.master);
287:     src.start();
288:   },
289: 
290:   hit(power) {
291:     if (!this.enabled || !this.ctx) return;
292:     if (this.ctx.currentTime - this.lastHit < 0.055) return;
293:     this.lastHit = this.ctx.currentTime;
294:     const v = clamp(power / 900, 0.04, 0.18);
295:     this.noise(0.075, v, 1500, 0.8);
296:     this.tone(64 + power * 0.035, 0.09, "sine", v * 0.75);
297:   },
298: 
299:   pickup(big) {
300:     this.tone(big ? 880 : 660, 0.07, "triangle", 0.075);
301:     this.tone(big ? 1320 : 990, 0.1, "sine", 0.045, 0.04);
302:   },
303: 
304:   jump() {
305:     this.tone(260, 0.07, "square", 0.028);
306:     this.tone(500, 0.11, "sine", 0.028, 0.03);
307:   },
308: 
309:   flip() {
310:     this.noise(0.13, 0.055, 520, 1.4);
311:     this.tone(180, 0.08, "sawtooth", 0.025);
312:   },
313: 
314:   count() {
315:     this.tone(440, 0.09, "sine", 0.06);
316:   },
317: 
318:   go() {
319:     this.tone(880, 0.18, "sine", 0.085);
320:     this.tone(1320, 0.24, "sine", 0.05, 0.02);
321:   },
322: 
323:   goal(good) {
324:     const notes = good ? [523, 659, 784, 1047] : [392, 330, 262];
325:     notes.forEach((n, i) => this.tone(n, 0.3, "triangle", 0.08, i * 0.12));
326:     this.noise(0.42, 0.06, 340, 0.7);
327:   },
328: 
329:   win() {
330:     [523, 659, 784, 1047, 1319].forEach((n, i) => this.tone(n, 0.42, "triangle", 0.085, i * 0.11));
331:   },
332: 
333:   lose() {
334:     [392, 349, 294, 196].forEach((n, i) => this.tone(n, 0.38, "sine", 0.075, i * 0.14));
335:   },
336: 
337:   click() {
338:     this.tone(620, 0.035, "sine", 0.022);
339:   }
340: };
