604: function scoreGoal(scorer) {
605:   if (G.phase !== "play") return;
606:   G.score[scorer] = Math.min(3, G.score[scorer] + 1);
607:   G.phase = "goal";
608:   G.goalTimer = 2.55;
609:   G.goalBy = scorer;
610:   G.goalLog.push({
611:     t: Number(G.time.toFixed(2)),
612:     scorer,
613:     ball: { x: Math.round(G.ball.x), y: Math.round(G.ball.y), z: Math.round(G.ball.z) },
614:     vel: { x: Math.round(G.ball.vx), y: Math.round(G.ball.vy) },
615:     touch: G.lastTouch,
616:     player: { x: Math.round(G.player.x), y: Math.round(G.player.y) },
617:     bot: { x: Math.round(G.bot.x), y: Math.round(G.bot.y) }
618:   });
619:   if (G.goalLog.length > 30) G.goalLog.shift();
620:   G.shake = Math.max(G.shake, 17);
621:   G.flash = 0.55;
622:   G.flashColor = scorer === 0 ? COLORS.cyan : COLORS.pink;
623:   G.input.boost = false;
624:   G.jumpQueued = false;
625:   G.player.boosting = false;
626:   G.bot.boosting = false;
627:   Sound.setBoost(false);
628:   spawnGoalBurst(scorer);
629:   Sound.goal(scorer === 0);
630:   announce(
631:     "GOAL!",
632:     scorer === 0 ? "YOU SCORE" : "BOT SCORES",
633:     scorer === 0 ? "go" : "pink",
634:     2100
635:   );
636:   updateScoreUI();
637: }
