884: function readTiltAxis(e) {
885:   const angle = (screen.orientation && screen.orientation.angle) || window.orientation || 0;
886:   if (angle === 90) return e.beta;
887:   if (angle === -90 || angle === 270) return e.beta == null ? null : -e.beta;
888:   if (angle === 180) return e.gamma == null ? null : -e.gamma;
889:   return e.gamma;
890: }
891: 
892: function onDeviceOrientation(e) {
893:   if (!G.tilt.enabled) return;
894:   const raw = readTiltAxis(e);
895:   if (raw == null || Number.isNaN(raw)) return;
896:   G.tilt.gotData = true;
897:   if (G.tilt.calibrating) {
898:     G.tilt.samples.push(raw);
899:     if (G.tilt.samples.length >= 18) {
900:       const sum = G.tilt.samples.reduce((a, b) => a + b, 0);
901:       G.tilt.zero = sum / G.tilt.samples.length;
902:       G.tilt.calibrating = false;
903:       G.tilt.ready = true;
904:       G.tilt.samples = [];
905:       syncTiltUI();
906:       showToast("Tilt ready — tilt left / right, push the stick to drive.", 3000);
907:     }
908:     return;
909:   }
910:   if (G.tilt.zero == null) G.tilt.zero = raw;
911:   const delta = raw - G.tilt.zero;
912:   const dead = 1.6;
913:   const max = 21;
914:   const sign = delta < 0 ? -1 : 1;
915:   G.tilt.target = sign * clamp((Math.abs(delta) - dead) / (max - dead), 0, 1);
916: }
