918: async function toggleTilt() {
919:   if (G.tilt.enabled) {
920:     G.tilt.enabled = false;
921:     G.tilt.ready = false;
922:     G.tilt.target = 0;
923:     G.tilt.value = 0;
924:     syncTiltUI();
925:     updateTiltMeterVisibility();
926:     showToast("Tilt steering off.");
927:     return;
928:   }
929: 
930:   if (typeof window.DeviceOrientationEvent === "undefined") {
931:     showToast("Motion tilt is not available on this device.");
932:     return;
933:   }
934: 
935:   if (typeof window.DeviceOrientationEvent.requestPermission === "function") {
936:     try {
937:       const result = await window.DeviceOrientationEvent.requestPermission();
938:       if (result !== "granted") {
939:         showToast("Motion access was denied. You can still drive with touch.");
940:         return;
941:       }
942:     } catch {
943:       showToast("Motion needs a secure page and a direct tap. Touch still works.");
944:       return;
945:     }
946:   }
947: 
948:   if (!G.tilt.listener) {
949:     window.addEventListener("deviceorientation", onDeviceOrientation, true);
950:     G.tilt.listener = true;
951:   }
952:   G.tilt.enabled = true;
953:   G.tilt.calibrating = true;
954:   G.tilt.ready = false;
955:   G.tilt.gotData = false;
956:   G.tilt.samples = [];
957:   G.tilt.zero = null;
958:   G.tilt.target = 0;
959:   G.tilt.value = 0;
960:   syncTiltUI();
961:   updateTiltMeterVisibility();
962:   showToast("Tilt on — hold your device naturally to calibrate.", 2600);
963: 
964:   const checkAt = performance.now();
965:   setTimeout(() => {
966:     if (G.tilt.enabled && !G.tilt.gotData && performance.now() - checkAt > 1200) {
967:       showToast("No motion data yet. On iPhone, allow Motion & Orientation access.", 3000);
968:     }
969:   }, 1700);
970: }
