1117:     p.life -= dt;
1118:     if (p.life <= 0) {
1119:       list.splice(i, 1);
1120:       continue;
1121:     }
1122:     p.vz -= p.grav * dt;
1123:     const drag = Math.pow(p.drag, dt * 60);
1124:     p.vx *= drag;
1125:     p.vy *= drag;
1126:     p.x += p.vx * dt;
1127:     p.y += p.vy * dt;
1128:     p.z += p.vz * dt;
1129:     p.rot += p.spin * dt;
1130:     if (p.z < 0) {
1131:       p.z = 0;
1132:       if (p.kind === "confetti") {
1133:         p.vz *= -0.35;
1134:         p.vx *= 0.7;
1135:         p.vy *= 0.7;
1136:       } else {
1137:         p.vz = 0;
1138:         p.vx *= 0.8;
1139:         p.vy *= 0.8;
