1159: function updateCar(car, input, dt) {
1160:   car.hitCd = Math.max(0, car.hitCd - dt);
1161:   car.flip = Math.max(0, car.flip - dt);
1162:   const ix = clamp(input.x || 0, -1, 1);
1163:   const iy = clamp(input.y || 0, -1, 1);
1164:   const rawMag = Math.hypot(ix, iy);
1165:   const mag = Math.min(1, rawMag);
1166:   const boosting = !!input.boost && car.boost > 0.2;
1167:   car.boosting = boosting;
1168: 
1169:   if (boosting) car.boost = Math.max(0, car.boost - 30 * dt);
1170: 
1171:   const air = !car.onGround;
1172:   const cap = boosting ? car.boostSpeed : car.baseSpeed * 1.04;
1173: 
1174:   if (mag > 0.06) {
1175:     const nx = ix / rawMag;
1176:     const ny = iy / rawMag;
1177:     const targetSpeed = cap * clamp(0.34 + mag * 0.82, 0.28, 1);
1178:     const rate = (boosting ? 7.4 : 5.4) * (air ? 0.36 : 1);
1179:     const k = 1 - Math.exp(-rate * dt);
1180:     car.vx = lerp(car.vx, nx * targetSpeed, k);
1181:     car.vy = lerp(car.vy, ny * targetSpeed, k);
1182:     car.angle = angleLerp(car.angle, Math.atan2(ny, nx), 1 - Math.exp(-(air ? 3.2 : 10.5) * dt));
1183:   } else {
1184:     const f = Math.exp(-(air ? 0.6 : 3.1) * dt);
1185:     car.vx *= f;
1186:     car.vy *= f;
1187:     if (boosting) {
1188:       car.vx += Math.cos(car.angle) * 1080 * dt;
1189:       car.vy += Math.sin(car.angle) * 1080 * dt;
1190:     }
1191:   }
1192: 
1193:   const sp = Math.hypot(car.vx, car.vy);
1194:   const speedCap = boosting ? car.boostSpeed : car.baseSpeed * 1.08;
1195:   if (sp > speedCap) {
1196:     car.vx = (car.vx / sp) * speedCap;
1197:     car.vy = (car.vy / sp) * speedCap;
1198:   }
1199: 
1200:   // Jump / air flip
1201:   if (input.jump) {
1202:     if (car.onGround) {
1203:       car.z = 0.5;
1204:       car.vz = 460;
1205:       car.onGround = false;
1206:       car.airJumps = 1;
1207:       Sound.jump();
1208:       spawnSparks(car.x, car.y, 4, 4, car.isPlayer ? COLORS.cyan : COLORS.pink, 90);
1209:     } else if (car.airJumps > 0) {
1210:       car.airJumps--;
1211:       car.vz = Math.max(car.vz, 255);
1212:       car.flip = 0.32;
1213:       const dashMag = Math.hypot(ix, iy);
1214:       const dx = dashMag > 0.08 ? ix / dashMag : Math.cos(car.angle);
1215:       const dy = dashMag > 0.08 ? iy / dashMag : Math.sin(car.angle);
1216:       car.vx += dx * 340;
1217:       car.vy += dy * 340;
1218:       car.angle = Math.atan2(dy, dx);
1219:       Sound.flip();
1220:       spawnSparks(car.x, car.y, car.z, 10, car.isPlayer ? COLORS.cyan : COLORS.pink, 200);
1221:     }
1222:   }
1223: 
1224:   if (!car.onGround) {
1225:     car.vz -= 1450 * dt;
1226:     car.z += car.vz * dt;
1227:     if (car.z <= 0) {
1228:       const impact = -car.vz;
1229:       car.z = 0;
1230:       car.vz = 0;
1231:       car.onGround = true;
1232:       car.flip = 0;
1233:       if (impact > 330) {
1234:         G.shake = Math.max(G.shake, 2.4);
1235:         spawnSparks(car.x, car.y, 2, 5, car.isPlayer ? COLORS.cyan : COLORS.pink, 100);
1236:       }
1237:     }
1238:   } else {
1239:     car.z = 0;
1240:   }
1241: 
1242:   car.x += car.vx * dt;
1243:   car.y += car.vy * dt;
1244: 
1245:   // Arena walls
1246:   const bx = FIELD.w / 2 - 31;
1247:   const by = FIELD.h / 2 - 36;
1248:   if (car.x < -bx) {
1249:     car.x = -bx;
1250:     if (car.vx < 0) car.vx *= -0.32;
1251:   } else if (car.x > bx) {
1252:     car.x = bx;
1253:     if (car.vx > 0) car.vx *= -0.32;
1254:   }
1255:   if (car.y < -by) {
1256:     car.y = -by;
1257:     if (car.vy < 0) car.vy *= -0.32;
1258:   } else if (car.y > by) {
1259:     car.y = by;
1260:     if (car.vy > 0) car.vy *= -0.32;
1261:   }
1262: 
1263:   // Boost exhaust
1264:   if (boosting) {
