1266:     if (car.fx <= 0) {
1267:       car.fx = 0.018;
1268:       const rx = car.x - Math.cos(car.angle) * CAR.l * 0.48;
1269:       const ry = car.y - Math.sin(car.angle) * CAR.l * 0.48;
1270:       particle({
1271:         x: rx + rand(-4, 4),
1272:         y: ry + rand(-4, 4),
1273:         z: car.z + rand(4, 14),
1274:         vx: -Math.cos(car.angle) * rand(50, 150) + car.vx * 0.08 + rand(-25, 25),
1275:         vy: -Math.sin(car.angle) * rand(50, 150) + car.vy * 0.08 + rand(-25, 25),
1276:         vz: rand(5, 60),
