1287: function updateBall(dt) {
1288:   const b = G.ball;
1289:   b.spin += Math.hypot(b.vx, b.vy) * dt * 0.055;
1290: 
1291:   if (b.z > BALL_R + 0.05 || b.vz > 0) {
1292:     b.vz -= 1500 * dt;
1293:     b.z += b.vz * dt;
1294:   }
1295: 
1296:   if (b.z < BALL_R) {
1297:     b.z = BALL_R;
1298:     if (b.vz < -65) {
1299:       b.vz = -b.vz * 0.6;
1300:       if (b.vz > 280) spawnSparks(b.x, b.y, BALL_R, 4, COLORS.white, 90);
1301:     } else {
1302:       b.vz = 0;
1303:     }
1304:     const f = Math.exp(-1.05 * dt);
1305:     b.vx *= f;
1306:     b.vy *= f;
1307:   } else {
1308:     const f = Math.exp(-0.06 * dt);
1309:     b.vx *= f;
1310:     b.vy *= f;
1311:   }
1312: 
1313:   const maxSpeed = 1650;
1314:   const sp = Math.hypot(b.vx, b.vy);
1315:   if (sp > maxSpeed) {
1316:     b.vx = (b.vx / sp) * maxSpeed;
1317:     b.vy = (b.vy / sp) * maxSpeed;
1318:   }
1319: 
1320:   b.x += b.vx * dt;
1321:   b.y += b.vy * dt;
1322: 
1323:   const lim = FIELD.w / 2 - BALL_R;
1324:   if (b.x < -lim) {
1325:     b.x = -lim;
1326:     b.vx = Math.abs(b.vx) * 0.83;
1327:     spawnSparks(b.x, b.y, b.z, 4, COLORS.cyanSoft, 120);
1328:   } else if (b.x > lim) {
1329:     b.x = lim;
1330:     b.vx = -Math.abs(b.vx) * 0.83;
1331:     spawnSparks(b.x, b.y, b.z, 4, COLORS.cyanSoft, 120);
1332:   }
1333: 
1334:   handlePosts();
1335:   checkGoal();
1336: }
