1338: function handlePosts() {
1339:   const b = G.ball;
1340:   const rr = BALL_R + 7;
1341:   for (const sx of [-1, 1]) {
1342:     for (const sy of [-1, 1]) {
1343:       const px = (sx * FIELD.goalW) / 2;
1344:       const py = (sy * FIELD.h) / 2;
1345:       const dx = b.x - px;
1346:       const dy = b.y - py;
1347:       const d2 = dx * dx + dy * dy;
1348:       if (d2 < rr * rr && d2 > 0.01) {
1349:         const d = Math.sqrt(d2);
1350:         const nx = dx / d;
1351:         const ny = dy / d;
1352:         b.x = px + nx * rr;
1353:         b.y = py + ny * rr;
1354:         const vn = b.vx * nx + b.vy * ny;
1355:         if (vn < 0) {
1356:           b.vx -= 1.72 * vn * nx;
1357:           b.vy -= 1.72 * vn * ny;
1358:           b.vx *= 0.82;
1359:           b.vy *= 0.82;
1360:           spawnSparks(px, py, b.z, 5, COLORS.gold, 160);
1361:           Sound.hit(260);
1362:         }
1363:       }
1364:     }
1365:   }
1366: }
