1368: function checkGoal() {
1369:   const b = G.ball;
1370:   const half = FIELD.h / 2;
1371:   const mouth = Math.abs(b.x) < FIELD.goalW / 2 - 3;
1372:   const underBar = b.z + BALL_R * 0.55 < FIELD.crossbar;
1373: 
1374:   if (b.y < -half) {
1375:     if (mouth && underBar) {
1376:       scoreGoal(0);
1377:       return;
1378:     }
1379:     b.y = -half + BALL_R;
1380:     if (b.vy < 0) b.vy = Math.abs(b.vy) * 0.8;
1381:     spawnSparks(b.x, -half, b.z, 3, COLORS.pinkSoft, 90);
1382:   } else if (b.y > half) {
1383:     if (mouth && underBar) {
1384:       scoreGoal(1);
1385:       return;
1386:     }
1387:     b.y = half - BALL_R;
1388:     if (b.vy > 0) b.vy = -Math.abs(b.vy) * 0.8;
1389:     spawnSparks(b.x, half, b.z, 3, COLORS.cyanSoft, 90);
1390:   }
