1393: function collideCarBall(car) {
1394:   if (car.hitCd > 0 || G.phase !== "play") return;
1395:   const b = G.ball;
1396:   const dx = b.x - car.x;
1397:   const dy = b.y - car.y;
1398:   const rr = CAR.radius + BALL_R;
1399:   const d2 = dx * dx + dy * dy;
1400:   if (d2 > rr * rr || d2 < 0.001) return;
1401:   if (b.z - BALL_R > car.z + 57) return;
1402:   if (b.z + BALL_R < car.z) return;
1403: 
1404:   const d = Math.sqrt(d2);
1405:   const nx = dx / d;
1406:   const ny = dy / d;
1407:   const overlap = rr - d;
1408:   b.x += nx * overlap;
1409:   b.y += ny * overlap;
1410: 
1411:   const cs = Math.hypot(car.vx, car.vy);
1412:   const rel = (b.vx - car.vx) * nx + (b.vy - car.vy) * ny;
1413:   const incoming = rel < -18;
1414:   if (!incoming && cs < 45) {
1415:     car.hitCd = 0.08;
1416:     return;
1417:   }
1418: 
1419:   let power = Math.max(0, -rel * 1.12) + cs * 0.58;
1420:   if (car.boosting) power += 170;
1421:   if (car.flip > 0) power += 300;
1422:   if (car.z > 18) power += 95;
1423:   power = clamp(power, 115, 1450);
1424: 
1425:   b.vx += nx * power + car.vx * 0.34;
1426:   b.vy += ny * power + car.vy * 0.34;
1427: 
1428:   let lift = 30 + cs * 0.12;
1429:   if (car.z > 12) lift += 130;
1430:   if (car.flip > 0) lift += 210;
1431:   b.vz = Math.max(b.vz, lift);
1432: 
1433:   const bs = Math.hypot(b.vx, b.vy);
1434:   if (bs > 1650) {
1435:     b.vx = (b.vx / bs) * 1650;
1436:     b.vy = (b.vy / bs) * 1650;
1437:   }
1438: 
1439:   car.hitCd = 0.075;
1440:   car.vx *= 0.92;
1441:   car.vy *= 0.92;
1442:   G.lastTouch = { who: car.isPlayer ? "player" : "bot", power: Math.round(power), t: Number(G.time.toFixed(2)) };
1443:   G.shake = Math.max(G.shake, clamp(power * 0.011, 0.5, 8));
1444:   spawnHitParticles(car, b, power);
1445:   Sound.hit(power);
1446: }
