1448: function collideCars() {
1449:   const p = G.player;
1450:   const b = G.bot;
1451:   const dx = b.x - p.x;
1452:   const dy = b.y - p.y;
1453:   const rr = CAR.radius * 1.72;
1454:   const d2 = dx * dx + dy * dy;
1455:   if (d2 > rr * rr || d2 < 0.01) return;
1456:   if (Math.abs(b.z - p.z) > 50) return;
1457:   const d = Math.sqrt(d2);
1458:   const nx = dx / d;
1459:   const ny = dy / d;
1460:   const push = (rr - d) / 2;
1461:   p.x -= nx * push;
1462:   p.y -= ny * push;
1463:   b.x += nx * push;
1464:   b.y += ny * push;
1465:   const rel = (b.vx - p.vx) * nx + (b.vy - p.vy) * ny;
1466:   if (rel < 0) {
1467:     const imp = -rel * 0.55;
1468:     p.vx -= nx * imp;
1469:     p.vy -= ny * imp;
1470:     b.vx += nx * imp;
1471:     b.vy += ny * imp;
1472:     if (imp > 90) {
1473:       spawnSparks((p.x + b.x) / 2, (p.y + b.y) / 2, Math.max(p.z, b.z) + 12, 6, COLORS.white, 170);
1474:       Sound.hit(imp * 2.4);
1475:       G.shake = Math.max(G.shake, 2.6);
1476:     }
1477:   }
1478: }
