1494:         pad.active = false;
1495:         pad.timer = pad.respawn;
1496:         if (car.isPlayer) Sound.pickup(pad.big);
1497:         for (let i = 0; i < (pad.big ? 16 : 8); i++) {
1498:           const a = rand(0, TAU);
1499:           particle({
1500:             x: pad.x,
1501:             y: pad.y,
1502:             z: rand(4, 20),
1503:             vx: Math.cos(a) * rand(30, 140),
1504:             vy: Math.sin(a) * rand(30, 140),
1505:             vz: rand(20, 120),
1506:             life: rand(0.25, 0.6),
