1521: function updateBotBrain(dt) {
1522:   const b = G.bot;
1523:   const ball = G.ball;
1524:   const diff = DIFF[G.difficulty];
1525: 
1526:   b.think -= dt;
1527:   if (b.think <= 0) {
1528:     b.think = Math.max(0.055, diff.reaction * rand(0.72, 1.32));
1529: 
1530:     const px = ball.x + ball.vx * 0.22;
1531:     const py = ball.y + ball.vy * 0.22;
1532:     let gx = 0 - px;
1533:     let gy = FIELD.h / 2 - py;
1534:     const gd = Math.hypot(gx, gy) || 1;
1535:     gx /= gd;
1536:     gy /= gd;
1537: 
1538:     const behind = 132 + clamp(Math.hypot(ball.vx, ball.vy) * 0.055, 0, 55);
1539:     let tx = px - gx * behind;
1540:     let ty = py - gy * behind;
1541: 
1542:     const bx = ball.x - b.x;
1543:     const by = ball.y - b.y;
1544:     const bd = Math.hypot(bx, by) || 1;
1545:     const align = (bx * gx + by * gy) / bd;
1546: 
1547:     if (bd < 310 && align > 0.08) {
1548:       tx = ball.x + gx * 112;
1549:       ty = ball.y + gy * 112;
1550:     }
1551: 
1552:     const dangerY = -FIELD.h / 2 + 330;
1553:     const danger = ball.y < dangerY && ball.y < b.y + 140;
1554:     if (danger) {
1555:       if (b.y < ball.y - 18) {
1556:         tx = ball.x;
1557:         ty = ball.y + 175;
1558:       } else {
1559:         const side = b.x >= ball.x ? 1 : -1;
1560:         tx = ball.x + side * 95;
1561:         ty = ball.y - 150;
1562:       }
1563:     }
1564: 
1565:     tx += rand(-1, 1) * diff.error * (danger ? 0.35 : 1);
1566:     ty += rand(-1, 1) * diff.error * (danger ? 0.35 : 1);
1567:     b.targetX = clamp(tx, -FIELD.w / 2 + 55, FIELD.w / 2 - 55);
1568:     b.targetY = clamp(ty, -FIELD.h / 2 + 44, FIELD.h / 2 - 70);
1569: 
1570:     const targetD = Math.hypot(b.targetX - b.x, b.targetY - b.y);
1571:     b.wantBoost = b.boost > 3 && Math.random() < diff.boostChance && (targetD > 285 || bd < 320);
1572: 
1573:     if (!b.onGround) {
1574:       if (b.airJumps > 0 && ball.z > 145 && bd < 145 && Math.random() < diff.jump * 0.4) {
1575:         b.jumpQueued = true;
1576:       }
1577:     } else if (ball.z > 95 && ball.z < 260 && bd < 150 && Math.random() < diff.jump * 0.2) {
1578:       b.jumpQueued = true;
1579:     }
1580:   }
1581: 
1582:   const dx = b.targetX - b.x;
1583:   const dy = b.targetY - b.y;
1584:   const d = Math.hypot(dx, dy);
1585:   let ix = d > 0.5 ? dx / d : 0;
1586:   let iy = d > 0.5 ? dy / d : 0;
1587: 
1588:   // Tiny human-ish wobble so it isn't perfectly robotic.
1589:   ix += Math.sin(G.time * 2.3 + 1.7) * 0.035;
1590:   iy += Math.cos(G.time * 1.9 + 0.4) * 0.035;
1591: 
1592:   const jump = b.jumpQueued;
1593:   b.jumpQueued = false;
1594:   return { x: ix, y: iy, boost: b.wantBoost && b.boost > 0.5, jump };
1595: }
