1599: function updateTilt(dt) {
1600:   const t = G.tilt;
1601:   if (!t.enabled) {
1602:     t.value = 0;
1603:     return;
1604:   }
1605:   t.value = lerp(t.value, t.target, 1 - Math.exp(-9 * dt));
