1608: function step(dt) {
1609:   if (G.shake > 0) G.shake = Math.max(0, G.shake - 46 * dt);
1610:   if (G.flash > 0) G.flash = Math.max(0, G.flash - dt * 1.8);
1611:   if (G.phase !== "paused") updateTilt(dt);
1612: 
1613:   if (G.phase === "menu") {
1614:     G.ball.spin += dt * 0.35;
1615:     G.ball.z = BALL_R + Math.sin(G.time * 1.4) * 16;
1616:     updateParticles(dt);
1617:     return;
1618:   }
1619: 
1620:   if (G.phase === "countdown") {
1621:     updateParticles(dt);
1622:     G.countdown -= dt;
1623:     const n = Math.ceil(G.countdown);
1624:     if (n > 0 && n !== G.lastCount) {
1625:       G.lastCount = n;
1626:       announce(String(n), "", "", 760);
1627:       Sound.count();
1628:     }
1629:     if (G.countdown <= 0) {
1630:       G.phase = "play";
1631:       G.lastCount = 0;
1632:       announce("GO!", "", "go", 720);
1633:       Sound.go();
1634:       G.shake = 2.6;
1635:       updateTag();
1636:       Sound.setBoost(false);
1637:     }
1638:     return;
1639:   }
1640: 
1641:   if (G.phase === "goal") {
1642:     updateParticles(dt);
1643:     G.goalTimer -= dt;
1644:     if (G.goalTimer <= 0) {
1645:       if (G.score[0] >= 3 || G.score[1] >= 3) finishMatch();
1646:       else beginKickoff();
1647:     }
1648:     return;
1649:   }
1650: 
1651:   if (G.phase === "gameover") {
1652:     updateParticles(dt);
1653:     if (G.endDelay > 0) {
1654:       G.endDelay -= dt;
1655:       if (G.endDelay <= 0) showEnd();
1656:     }
1657:     return;
1658:   }
1659: 
1660:   if (G.phase !== "play") return;
1661: 
1662:   const pInput = getPlayerInput();
1663:   const bInput = updateBotBrain(dt);
1664:   updateCar(G.player, pInput, dt);
1665:   updateCar(G.bot, bInput, dt);
1666:   collideCars();
1667:   updateBall(dt);
1668:   if (G.phase === "play") {
1669:     collideCarBall(G.player);
1670:     collideCarBall(G.bot);
1671:   }
1672:   updatePads(dt);
1673:   updateParticles(dt);
1674:   updateTrail(dt);
1675:   const wantBoostSound = G.player.boosting && G.sound;
1676:   if (wantBoostSound !== G.boostSound) {
1677:     G.boostSound = wantBoostSound;
1678:     Sound.setBoost(wantBoostSound);
1679:   }
1680:   G.lastUI.tag = "";
1681: }
