1685: function roundRectPath(x, y, w, h, r) {
1686:   const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
1687:   ctx.beginPath();
1688:   ctx.moveTo(x + rr, y);
1689:   ctx.arcTo(x + w, y, x + w, y + h, rr);
1690:   ctx.arcTo(x + w, y + h, x, y + h, rr);
1691:   ctx.arcTo(x, y + h, x, y, rr);
1692:   ctx.arcTo(x, y, x + w, y, rr);
1693:   ctx.closePath();
1694: }
