  const addGoal = async scorer => {
    await page.evaluate(s => window.__rocketDuel.scoreGoal(s), scorer);
    if (await page.evaluate(() => window.__rocketDuel.G.phase) === 'gameover') {
      await page.waitForFunction(() => !document.querySelector('#end').classList.contains('is-hidden'));
    } else {
      await page.waitForFunction(() => window.__rocketDuel.G.phase === 'play');
    }
  };
  await addGoal(0); await addGoal(0); await addGoal(1);
  const result = await page.evaluate(() => ({ phase: window.__rocketDuel.G.phase, score: [...window.__rocketDuel.G.score], endVisible: !document.querySelector('#end').classList.contains('is-hidden'), finalScore: document.querySelector('#finalScore').textContent.trim() }));
  if (result.phase !== 'gameover' || result.score.join(',') !== '2,1' || !result.endVisible) throw new Error(`Unexpected result state ${JSON.stringify(result)}`);
  // ScoreGoal can only end a match at 3; finish deterministically by awarding the final player goal.
  await page.evaluate(() => { window.__rocketDuel.G.phase = 'play'; window.__rocketDuel.scoreGoal(0); });
  await page.waitForFunction(() => !document.querySelector('#end').classList.contains('is-hidden'));
  const finalScore = await page.locator('#finalScore').innerText();
  await page.locator('#rematchBtn').click();
  const rematch = await page.evaluate(() => ({ phase: window.__rocketDuel.G.phase, score: [...window.__rocketDuel.G.score], endHidden: document.querySelector('#end').classList.contains('is-hidden'), menuHidden: document.querySelector('#menu').classList.contains('is-hidden') }));
  if (rematch.phase !== 'countdown' || rematch.score.join(',') !== '0,0' || !rematch.endHidden || !rematch.menuHidden) throw new Error(`Rematch failed: ${JSON.stringify(rematch)}`);
  await page.waitForFunction(() => window.__rocketDuel.G.phase === 'play');
  await page.screenshot({ path: 'screenshots/rocket-rematch.jpg', type: 'jpeg', quality: 72 });
  // MAIN MENU navigation from a result screen.
  await page.evaluate(() => { window.__rocketDuel.finishMatch(); });
  await page.waitForFunction(() => window.__rocketDuel.G.phase === 'gameover');
  await page.evaluate(() => { window.__rocketDuel.G.score = [0, 3]; window.__rocketDuel.updateUI(true); });
  await page.evaluate(() => { document.querySelector('#endMenuBtn').click(); });
  const menu = await page.evaluate(() => ({ phase: window.__rocketDuel.G.phase, score: [...window.__rocketDuel.G.score], menuVisible: !document.querySelector('#menu').classList.contains('is-hidden'), endHidden: document.querySelector('#end').classList.contains('is-hidden') }));
  if (menu.phase !== 'menu' || menu.score.join(',') !== '0,0' || !menu.menuVisible || !menu.endHidden) throw new Error(`Main menu navigation failed: ${JSON.stringify(menu)}`);
  // Pause then restart from the pause panel.
  await page.locator('#playBtn').click();
  await page.locator('#pauseBtn').click();
  if (await page.evaluate(() => window.__rocketDuel.G.phase) !== 'paused') throw new Error('Pause button did not pause match');
  await page.locator('#restartBtn').click();
  const restart = await page.evaluate(() => ({ phase: window.__rocketDuel.G.phase, score: [...window.__rocketDuel.G.score], pauseHidden: document.querySelector('#pause').classList.contains('is-hidden') }));
  if (restart.phase !== 'countdown' || restart.score.join(',') !== '0,0' || !restart.pauseHidden) throw new Error(`Pause restart failed: ${JSON.stringify(restart)}`);
  console.log(JSON.stringify({ result, finalScore, rematch, menu, restart, issues }, null, 2));
  await browser.close();
})().catch(err => { console.error(err); process.exitCode = 1; });
